const DATE_WINDOW_DAYS = 45;
const AMOUNT_BAND_MULTIPLIER = 4;

function findEvidence(settlementAbsAmount, settlementDate, bucketFilter, settlementVendor, requireVendorMatch) {
  let best = null;
